void mainImage(out vec4 N, vec2 g) {
    vec3 R = iResolution,
         j = vec3((g + g - R.xy) / R.y, 1.8) * mat3(2, 1, 1, -1, 2, 2, -1, -2, 2) * .15,
         a, q, k;
    float t = iTime * .25, o = 0., e, b, c;

    for (N -= N, k.y = -5.; N.a < 12. && o++ < 90.;
         b = max(b, 0.),
         N += (1. - exp(-b * vec4(128, 32, 8, 1))) * (.015 + .004 * cos(e - t * 8. + vec4(0, 2, 4, 0))) / (b * 80. + .05),
         k += j * max(b, .002) * e * .18)

        for (e = length(k),
             q = k,
             q.xz *= mat2(cos(log(e) * .6 - t + vec4(0, 11, 33, 0))),
             a = vec3(fract((log(e) - t) * .12) * 6., exp(-q.y / e), atan(q.x, q.z) * 1.5),
             b = a.y - .25,
             c = 3.;
             c < 4e2;
             c += c)

            b -= abs(dot(sin(a.yzx * c + t), cos(a.zxy * c))) * .7 / c;

    N = 1. - exp(-N * N * 1.8);
}
